// Personal cyberdeck loadouts. Entries are independent copies; they do not mutate inventory.
const deckObj=x=>!!x&&typeof x==='object'&&!Array.isArray(x),deckInt=(x,a,b)=>Number.isSafeInteger(x)&&x>=a&&x<=b;
function deckCatalog(id){if(!Array.isArray(window.CATALOG)||typeof id!=='string')return null;const a=window.CATALOG.filter(x=>x?.id===id&&x.category==='programs');if(a.length!==1)return null;const p=a[0],s=p.stats;if(!deckObj(s)||!deckObj(p.name)||typeof p.name.ru!=='string'||typeof p.name.en!=='string'||!p.name.ru||!p.name.en||p.name.ru.length>200||p.name.en.length>200)return null;let kind,slots;if(s.type==='hardware'){kind='hardware';slots=s.slots}else if(s.type==='black-ice'){kind='ice';slots=2}else if(['booster','defender','anti-program','anti-personnel'].includes(s.type)){kind='program';slots=1}else return null;if(!deckInt(slots,1,2))return null;return {p,kind,slots}}
function deckState(c){if(!deckObj(c)||c.extra!==undefined&&!deckObj(c.extra))return {kind:'invalid'};const x=c.extra?.cyberdecks;if(x===undefined)return {kind:'new'};if(!deckObj(x)||x.version!==1||!Array.isArray(x.decks)||x.decks.length>20)return {kind:'invalid'};const deckIds=new Set();for(const d of x.decks){if(!deckObj(d)||typeof d.id!=='string'||!d.id||d.id.length>160||deckIds.has(d.id)||typeof d.name!=='string'||!d.name.trim()||d.name.length>100||!deckInt(d.slots,1,30)||!deckInt(d.hardwareOnly,0,10)||!Array.isArray(d.entries)||d.entries.length>40)return {kind:'invalid'};deckIds.add(d.id);let ids=new Set(),used=0,nonHardware=0;for(const e of d.entries){if(!deckObj(e)||typeof e.id!=='string'||!e.id||e.id.length>160||ids.has(e.id)||typeof e.catalogId!=='string'||!e.catalogId||e.catalogId.length>160||!deckObj(e.name)||typeof e.name.ru!=='string'||typeof e.name.en!=='string'||!e.name.ru||!e.name.en||e.name.ru.length>200||e.name.en.length>200||!['hardware','ice','program'].includes(e.kind)||!deckInt(e.slots,1,2)||e.kind==='program'&&e.slots!==1||e.kind==='ice'&&e.slots!==2)return {kind:'invalid'};ids.add(e.id);used+=e.slots;if(e.kind!=='hardware')nonHardware+=e.slots}if(nonHardware>d.slots||used>d.slots+d.hardwareOnly)return {kind:'invalid'}}return {kind:'ok',value:x}}
function deckEntryDetails(e,l){const p=deckCatalog(e.catalogId);if(!p||p.kind!==e.kind||p.slots!==e.slots)return '';const stats=p.p.stats,values=e.kind==='hardware'?'':`ATK ${stats.atk} · DEF ${stats.def} · REZ ${stats.rez}`,details=p.p.details?.[l];return [values,typeof details==='string'?details:''].filter(Boolean).join(' · ')}
function deckRender(c,l){const ru=l==='ru',s=deckState(c),tx=(r,e)=>ru?r:e;let h=`<section class="rt-section" data-deck-root><div class="rt-subhead">${tx('КИБЕРДЕКИ','CYBERDECKS')} · 196–197, 201, 204, 208</div><p class="rt-help">${tx('Ведите установленные копии и слоты. Программы и Hardware занимают общие слоты; Black ICE занимает 2. Дополнительные слоты Bodyweight Suit предназначены только для Hardware. Установка или снятие каждой программы и модуля занимает час. Инвентарь, деньги, NET-действия, активность и REZ учитывайте вручную.','Track installed copies and slots. Programs and Hardware share slots; Black ICE uses 2. Extra Bodyweight Suit slots are for Hardware only. Installing or removing each program or module takes one hour. Track inventory, cash, NET Actions, activation and REZ manually.')}</p>`;if(s.kind==='invalid')return h+`<p class="rt-warning">${tx('Формат дек несовместим; данные не изменены.','Cyberdeck data is incompatible; it was not changed.')}</p></section>`;
 h+=`<div class="rt-grid"><label class="rt-field">${tx('Название деки','Deck name')}<input data-deck-name maxlength="100"></label><label class="rt-field">${tx('Общие слоты','General slots')}<input data-deck-slots type="number" min="1" max="30" value="7"></label><label class="rt-field">${tx('Слоты только Hardware','Hardware-only slots')}<input data-deck-hardware type="number" min="0" max="10" value="0"></label></div><p class="rt-help">${tx('Базовая дека: Poor Quality — 5, стандартная — 7, Excellent Quality — 9 слотов. Учтите дополнительные слоты вручную. Для работы нужны Neural Link и Interface Plugs.','Base decks: Poor Quality 5, standard 7, Excellent Quality 9 slots. Add extra slots manually. Neural Link and Interface Plugs are required to use a deck.')}</p>${button(l,'deck-create','Сохранить деку','Save deck')}`;
 const all=(Array.isArray(window.CATALOG)?window.CATALOG:[]).filter(p=>deckCatalog(p?.id)?.p===p);for(const d of s.value?.decks||[]){let used=d.entries.reduce((n,e)=>n+e.slots,0);h+=`<div class="rt-mini" data-deck-id="${esc(d.id)}"><strong>${esc(d.name)}</strong><p>${tx('Занято слотов','Slots used')}: ${used} / ${d.slots} + ${d.hardwareOnly} ${tx('только Hardware','hardware only')}</p><div class="rt-grid"><label class="rt-field">${tx('Название деки','Deck name')}<input data-deck-rename maxlength="100" value="${esc(d.name)}"></label><label class="rt-field">${tx('Общие слоты','General slots')}<input data-deck-capacity type="number" min="1" max="30" value="${d.slots}"></label><label class="rt-field">${tx('Слоты только Hardware','Hardware-only slots')}<input data-deck-only type="number" min="0" max="10" value="${d.hardwareOnly}"></label></div>${button(l,'deck-update','Сохранить изменения','Save changes')}<div class="rt-grid"><label class="rt-field">${tx('Программа или Hardware','Program or Hardware')}<select data-deck-item><option value="">${tx('Выберите','Choose')}</option>${all.map(p=>`<option value="${esc(p.id)}">${esc(p.name[l])} · ${deckCatalog(p.id).slots} ${tx('сл.','slot(s)')}</option>`).join('')}</select></label></div>${button(l,'deck-install','Установить экземпляр','Install copy')} ${button(l,'deck-delete','Удалить деку','Delete deck')}<ul>${d.entries.map(e=>`<li>${esc(e.name[l])} · ${e.slots} ${tx('сл.','slot(s)')} <button type="button" class="rt-button" data-rt-action="deck-remove" data-deck-entry="${esc(e.id)}">${tx('Снять','Remove')}</button>${deckEntryDetails(e,l)?`<p class="rt-help">${esc(deckEntryDetails(e,l))}</p>`:''}</li>`).join('')}</ul></div>`}return h+'</section>'}
